INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2500, 'ratification', '/ˌrætɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["批准；認可"],"en":["the formal approval of an agreement by authorized parties"]}', NULL, 'ratification of a treaty / board ratification / pending ratification', '[{"en":"The merger required shareholder ratification at the AGM.","zh-TW":"合併需要在年度股東大會上獲得股東批准。"},{"en":"Ratification of the agreement was delayed by legal review.","zh-TW":"協議的批准因法律審查而延遲。"}]', '{"verb":"ratify"}', NULL, 4, 2500, NULL),
(2501, 'ratio', '/ˈreɪʃioʊ/', 'noun', '{"zh-TW":["比率；比例"],"en":["the relationship between two numbers"]}', '{"root":{"text":"rat","meaning":"reckon (計算)"}}', 'debt-to-equity ratio / ratio of...to... / maintain a ratio', '[{"en":"The debt-to-equity ratio is 2:1.","zh-TW":"債務權益比為2:1。"},{"en":"What is the ratio of managers to employees?","zh-TW":"經理與員工的比例是多少？"}]', NULL, NULL, 2, 2501, NULL),
(2502, 'rational', '/ˈræʃənəl/', 'adjective', '{"zh-TW":["理性的；合理的"],"en":["based on reason; logical"]}', '{"root":{"text":"ration","meaning":"reason (理性)"},"suffix":{"text":"-al","meaning":"...的"}}', 'rational decision / rational thinking / rational approach', '[{"en":"We need to make a rational decision.","zh-TW":"我們需要做出理性決定。"},{"en":"His approach was entirely rational.","zh-TW":"他的方法完全合理。"}]', '{"noun":"rationality, rationale","adverb":"rationally","verb":"rationalize"}', NULL, 3, 2502, NULL),
(2503, 'rationale', '/ˌræʃəˈnɑːl/', 'noun', '{"zh-TW":["基本原理；理由"],"en":["the underlying reasons for a decision or action"]}', NULL, 'provide a rationale / explain the rationale', '[{"en":"Please provide the rationale for this budget request.","zh-TW":"請提供此預算申請的理由。"},{"en":"The rationale behind the restructuring was to improve efficiency.","zh-TW":"重組背後的基本原理是提高效率。"}]', NULL, NULL, 3, 2503, NULL),
(2504, 'raw', '/rɔː/', 'adjective', '{"zh-TW":["原始的；未加工的"],"en":["not processed; in natural state"]}', NULL, 'raw materials / raw data / raw talent', '[{"en":"The cost of raw materials has increased.","zh-TW":"原材料成本已增加。"},{"en":"We need to analyze the raw data.","zh-TW":"我們需要分析原始數據。"}]', NULL, NULL, 1, 2504, NULL),
(2505, 'reach', '/riːtʃ/', 'verb', '{"zh-TW":["到達；達到"],"en":["to arrive at","to achieve"]}', NULL, 'reach an agreement / reach out', '[{"en":"We reached an agreement after long talks.","zh-TW":"經過長時間談判我們達成了協議。"},{"en":"Feel free to reach out anytime.","zh-TW":"隨時可以聯繫我們。"}]', '{"verb":"reach","noun":"reach"}', NULL, 2, 2505, NULL),
(2506, 'react', '/riˈækt/', 'verb', '{"zh-TW":["反應；回應"],"en":["to respond to something"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"act","meaning":"do (做)"}}', 'react to / react quickly / react negatively', '[{"en":"How did the market react to the news?","zh-TW":"市場對這消息如何反應？"},{"en":"She reacted quickly to the crisis.","zh-TW":"她對危機迅速做出反應。"}]', '{"noun":"reaction","adjective":"reactive"}', NULL, 2, 2506, NULL),
(2507, 'read', '/riːd/', 'verb', '{"zh-TW":["閱讀"],"en":["to look at and understand written words"]}', NULL, 'read carefully / well-read', '[{"en":"Please read the contract carefully.","zh-TW":"請仔細閱讀合約。"},{"en":"She is well-read in business literature.","zh-TW":"她廣泛閱讀商業文獻。"}]', '{"verb":"read","noun":"reader","noun2":"reading","adjective":"readable"}', NULL, 1, 2507, NULL),
(2508, 'ready', '/ˈrɛdi/', 'adjective', '{"zh-TW":["準備好的"],"en":["prepared for action"]}', NULL, 'get ready / ready-made', '[{"en":"Are you ready for the presentation?","zh-TW":"你準備好報告了嗎？"},{"en":"We offer ready-made solutions.","zh-TW":"我們提供現成的解決方案。"}]', '{"adjective":"ready","noun":"readiness","verb":"ready"}', NULL, 2, 2508, NULL),
(2509, 'real', '/riːl/', 'adjective', '{"zh-TW":["真實的；實際的"],"en":["actually existing","genuine"]}', NULL, 'real estate / in real time', '[{"en":"She works in real estate.","zh-TW":"她從事房地產業。"},{"en":"We track data in real time.","zh-TW":"我們即時追蹤數據。"}]', '{"adjective":"real","noun":"reality","adverb":"really","adjective2":"realistic","verb":"realize"}', NULL, 1, 2509, NULL),
(2510, 'realistic', 'rɪəˈlɪstɪk', 'adjective', '{"zh-TW":["現實的；實際的","可行的"],"en":["sensible and practical","based on reality"]}', NULL, 'realistic goal/realistic expectation', '[{"en":"Set realistic goals for the team.","zh-TW":"為團隊設定現實目標。"}]', '{"noun":"realism","adverb":"realistically"}', NULL, 3, 2510, NULL),
(2511, 'realize', '/ˈriːəlaɪz/', 'verb', '{"zh-TW":["【主要意義-動詞】意識到；理解","【次要意義-動詞】獲得（利潤）；實現（資產變現）","【次要意義-動詞】實現；成就（計劃）"],"en":["[primary] to become aware of a fact or situation","[secondary] to make a profit from selling assets; to convert assets to cash","[secondary] to achieve something that was planned"]}', '{"root":{"text":"real","meaning":"real (真實)"},"suffix":{"text":"-ize","meaning":"使...化"}}', 'realize a profit / realize assets / realize a goal / realize potential', '[{"en":"The company realized a substantial profit from the sale of its subsidiary.","zh-TW":"公司從出售子公司中獲得了可觀的利潤。"},{"en":"The new plan will help the organization realize its long-term strategic goals.","zh-TW":"新計劃將幫助組織實現其長期戰略目標。"},{"en":"Investors realized gains when the stock price hit a record high.","zh-TW":"當股價創下歷史新高時，投資者實現了收益。"}]', '{"noun":"realization"}', 'realize a profit/gain = 「實現（獲得）利潤/收益」是 TOEIC 財務文章的高頻表達，realize a goal = 「實現目標」也常見，考生常誤以為 realize 只有「意識到」的意思。', 3, 2511, NULL),
(2512, 'reason', '/ˈriːzən/', 'noun', '{"zh-TW":["原因；理由"],"en":["the cause or explanation for something"]}', NULL, 'for this reason / the reason why / reason for / reasonable', '[{"en":"For this reason, we decided to postpone.","zh-TW":"基於這個原因，我們決定延期。"},{"en":"What is the reason for the delay?","zh-TW":"延遲的原因是什麼？"}]', '{"adjective":"reasonable","adverb":"reasonably","verb":"reason"}', NULL, 2, 2512, NULL),
(2513, 'reasonable', '/ˈriːzənəbl/', 'adjective', '{"zh-TW":["合理的；適當的"],"en":["fair; sensible; not too expensive"]}', '{"root":{"text":"reason","meaning":"reason (理由)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reasonable price / reasonable request / within a reasonable time', '[{"en":"The price seems reasonable for the quality.","zh-TW":"就品質而言價格合理。"},{"en":"Please respond within a reasonable timeframe.","zh-TW":"請在合理時間內回覆。"}]', '{"adverb":"reasonably","noun":"reasonableness"}', NULL, 4, 2513, NULL),
(2514, 'rebate', '/ˈriːbeɪt/', 'noun', '{"zh-TW":["回扣；折讓"],"en":["a partial refund or discount given after a purchase"]}', NULL, 'offer a rebate / volume rebate / claim a rebate / rebate program', '[{"en":"The manufacturer offered a $50 rebate on purchases over $200.","zh-TW":"製造商對超過200美元的購買提供50美元的回扣。"},{"en":"Volume rebates incentivize customers to buy in larger quantities.","zh-TW":"數量折讓激勵客戶以更大的數量購買。"}]', '{"verb":"rebate"}', NULL, 2, 2514, NULL),
(2515, 'rebranding', '/riːˈbrændɪŋ/', 'noun', '{"zh-TW":["重新品牌化；品牌重塑"],"en":["changing the brand identity of an existing company or product"]}', NULL, 'undergo rebranding / rebranding campaign / successful rebranding', '[{"en":"The rebranding campaign refreshed the company''s outdated image.","zh-TW":"重新品牌化活動更新了公司過時的形象。"},{"en":"Rebranding was necessary after the merger to unify identities.","zh-TW":"合併後需要重新品牌化以統一品牌形象。"}]', '{"verb":"rebrand"}', NULL, 4, 2515, NULL),
(2516, 'receipt', '/rɪˈsiːt/', 'noun', '{"zh-TW":["收據","收據；收到"],"en":["a written acknowledgment of payment","a written proof of payment"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ceipt","meaning":"take (拿取)"},"logic":"拿回的證明，即「收據」。"}', 'keep the receipt / receipt printer; keep the receipt / upon receipt of / acknowledge receipt', '[{"en":"Please keep your receipt for returns.","zh-TW":"請保留收據以便退貨。"},{"en":"The receipt shows the date of purchase.","zh-TW":"收據上顯示購買日期。"},{"en":"Upon receipt of your payment, we will ship the order.","zh-TW":"收到付款後我們將發貨。"}]', NULL, NULL, 3, 2516, 190),
(2517, 'receivable', '/rɪˈsiːvəbəl/', 'noun', '{"zh-TW":["應收帳款"],"en":["money owed to a business by its customers"]}', NULL, 'accounts receivable / collect receivables', '[{"en":"Accounts receivable totaled $3 million.","zh-TW":"應收帳款總計300萬美元。"},{"en":"We need to collect outstanding receivables.","zh-TW":"我們需要收取未結應收帳款。"}]', '{"noun":"receivable","adjective":"receivable","verb":"receive"}', NULL, 4, 2517, 917),
(2518, 'receivables', '/rɪˈsiːvəbəlz/', 'noun', '{"zh-TW":["應收帳款"],"en":["amounts owed to a company for goods or services already delivered"]}', NULL, 'collect receivables / days receivables outstanding', '[{"en":"The company improved cash flow by accelerating collection of receivables.","zh-TW":"公司通過加速應收帳款的收款改善了現金流。"},{"en":"Factoring receivables provides immediate liquidity.","zh-TW":"應收帳款保理提供了即時流動性。"}]', NULL, NULL, 4, 2518, NULL),
(2519, 'receive', '/rɪˈsiːv/', 'verb', '{"zh-TW":["收到；接受"],"en":["to get something that is sent or given"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ceive","meaning":"take (拿取)"}}', 'receive a letter / receive feedback / receive approval', '[{"en":"We received your application yesterday.","zh-TW":"我們昨天收到了你的申請。"},{"en":"The project received full approval.","zh-TW":"項目獲得了全面批准。"}]', '{"noun":"receipt, receiver, reception","adjective":"receivable"}', NULL, 3, 2519, 191),
(2520, 'receivership', '/rɪˈsiːvərʃɪp/', 'noun', '{"zh-TW":["接管；破產接管"],"en":["a legal process in which a receiver takes control of a company to manage its assets"]}', NULL, 'enter receivership / company in receivership', '[{"en":"The failing company was placed into receivership by the courts.","zh-TW":"法院將破產公司置於接管之下。"},{"en":"A receivership aims to repay creditors by managing and selling assets.","zh-TW":"接管旨在通過管理和出售資產來償還債權人。"}]', NULL, NULL, 4, 2520, NULL),
(2521, 'receiving', '/rɪˈsiːvɪŋ/', 'noun', '{"zh-TW":["收貨；驗收"],"en":["the process of accepting and inspecting incoming goods at a warehouse"]}', NULL, 'receiving department / receiving dock / receiving process', '[{"en":"All incoming goods go through the receiving department first.","zh-TW":"所有進貨先經過收貨部門處理。"},{"en":"The receiving team inspects shipments against purchase orders.","zh-TW":"收貨團隊根據採購訂單核查貨物。"}]', '{"verb":"receive","noun":"receiver"}', NULL, 3, 2521, NULL),
(2522, 'recent', '/ˈriːsənt/', 'adjective', '{"zh-TW":["最近的；近來的"],"en":["happening a short time ago"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cent","meaning":"new (新)"}}', 'in recent years / recent developments / most recent', '[{"en":"In recent years, the company has expanded rapidly.","zh-TW":"近年來公司快速擴張。"},{"en":"What are the most recent developments?","zh-TW":"最新的進展是什麼？"}]', '{"adverb":"recently"}', NULL, 2, 2522, NULL),
(2523, 'reception', '/rɪˈsɛpʃən/', 'noun', '{"zh-TW":["接待處；大廳"],"en":["the area of a hotel where guests are welcomed"]}', NULL, 'hotel reception / check in at reception', '[{"en":"Please ask at reception for any assistance.","zh-TW":"如需任何協助，請向接待處詢問。"},{"en":"Reception will hold your luggage until check-in time.","zh-TW":"接待處將為您保管行李直到入住時間。"}]', '{"verb":"receive","adjective":"receptive"}', NULL, 3, 2523, NULL),
(2524, 'recession', '/rɪˈseʃən/', 'noun', '{"zh-TW":["經濟衰退"],"en":["a significant decline in economic activity lasting more than two quarters"]}', NULL, 'economic recession / survive a recession / enter a recession / recession-proof', '[{"en":"The company survived the recession by cutting costs aggressively.","zh-TW":"公司通過積極削減成本度過了經濟衰退。"},{"en":"A recession typically leads to reduced consumer spending.","zh-TW":"經濟衰退通常導致消費者支出減少。"}]', '{"adjective":"recessionary"}', NULL, 3, 2524, NULL),
(2525, 'recipient', '/rɪˈsɪpiənt/', 'noun', '{"zh-TW":["接收者；收件人"],"en":["a person who receives something"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"cipient","meaning":"take (拿取)"}}', 'award recipient / email recipient / intended recipient', '[{"en":"The recipient of the award was announced.","zh-TW":"獎項得主已公佈。"},{"en":"Please confirm the recipient''s email address.","zh-TW":"請確認收件人的電郵地址。"}]', NULL, NULL, 3, 2525, NULL),
(2526, 'recognition', '/ˌrɛkəɡˈnɪʃən/', 'noun', '{"zh-TW":["認可；表彰","認出","認可；識別"],"en":["acknowledgment; appreciation","identifying someone","acknowledgment; the act of identifying"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cogn","meaning":"know (知道)"},"suffix":{"text":"-ition","meaning":"行為"}}', 'in recognition of / gain recognition / brand recognition', '[{"en":"She received recognition for her contributions.","zh-TW":"她因貢獻而獲得表彰。"},{"en":"Brand recognition has improved significantly.","zh-TW":"品牌認知度顯著提升。"},{"en":"She won recognition for her work.","zh-TW":"她的工作獲得了認可。"},{"en":"Brand recognition is essential for growth.","zh-TW":"品牌認知對成長至關重要。"}]', '{"verb":"recognize","adjective":"recognizable"}', NULL, 4, 2526, 432),
(2527, 'recognize', '/ˈrɛkəɡnaɪz/', 'verb', '{"zh-TW":["認出；承認","認可"],"en":["to identify","to acknowledge"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cogn","meaning":"know (知道)"},"suffix":{"text":"-ize","meaning":"使..."}}', 'recognize the importance / widely recognized / recognize sb.', '[{"en":"We recognize the need for improvement.","zh-TW":"我們認識到需要改進。"},{"en":"She is widely recognized as an expert.","zh-TW":"她被廣泛認為是專家。"}]', '{"noun":"recognition","adjective":"recognizable"}', NULL, 3, 2527, 192),
(2528, 'recommend', '/ˌrɛkəˈmɛnd/', 'verb', '{"zh-TW":["推薦；建議"],"en":["to suggest as good; to advise"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"commend","meaning":"praise (讚美)"}}', 'highly recommend / recommend that / recommend sb. for', '[{"en":"I highly recommend this software.","zh-TW":"我強力推薦這個軟體。"},{"en":"The committee recommends that we proceed.","zh-TW":"委員會建議我們繼續。"}]', '{"noun":"recommendation"}', NULL, 3, 2528, 50),
(2529, 'recommendation', 'ˌrɛkəmɛnˈdeɪʃən', 'noun', '{"zh-TW":["建議；推薦","意見"],"en":["advice given","a positive suggestion"]}', NULL, 'make a recommendation/follow recommendations', '[{"en":"The committee made several recommendations.","zh-TW":"委員會提出了幾項建議。"}]', '{"verb":"recommend","adjective":"recommended"}', NULL, 5, 2529, 612),
(2530, 'reconcile', '/ˈrɛkənsaɪl/', 'verb', '{"zh-TW":["調和；使一致"],"en":["to make compatible; to settle differences"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"concile","meaning":"bring together (聚集)"}}', 'reconcile differences / reconcile accounts / hard to reconcile', '[{"en":"We need to reconcile the accounts by month-end.","zh-TW":"我們需要在月底前核對帳目。"},{"en":"It''s hard to reconcile the conflicting reports.","zh-TW":"很難調和相互矛盾的報告。"}]', '{"noun":"reconciliation"}', NULL, 3, 2530, 711),
(2531, 'reconciliation', '/ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["帳目核對；對帳"],"en":["the process of comparing two sets of records to ensure they agree"]}', NULL, 'bank reconciliation / account reconciliation / monthly reconciliation', '[{"en":"Monthly bank reconciliation catches discrepancies early.","zh-TW":"月度銀行對帳能早期發現差異。"},{"en":"The accountant performed a reconciliation of all expense accounts.","zh-TW":"會計師對所有費用帳戶進行了對帳。"}]', '{"verb":"reconcile","adjective":"reconciled"}', NULL, 5, 2531, 809),
(2532, 'record', '/rɪˈkɔːrd/', 'verb', '{"zh-TW":["記錄","錄製"],"en":["to write down; to make a note","to capture audio/video"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cord","meaning":"heart (心)"}}', 'keep a record / on record / record-breaking / set a record', '[{"en":"All transactions are recorded in the system.","zh-TW":"所有交易都記錄在系統中。"},{"en":"Sales reached a record high this quarter.","zh-TW":"本季度銷售額創歷史新高。"}]', '{"noun":"record, recording","adjective":"recorded"}', NULL, 2, 2532, 193),
(2533, 'recourse', '/rɪˈkɔːrs/', 'noun', '{"zh-TW":["追索權；補救手段"],"en":["the right to demand compensation from a party if another fails to pay"]}', NULL, 'have recourse against / limited recourse', '[{"en":"The contract includes recourse provisions if the supplier defaults.","zh-TW":"合約包含了供應商違約時的追索權條款。"},{"en":"A non-recourse loan means the lender can only claim the collateral.","zh-TW":"無追索權貸款意味著貸款方只能索取抵押品。"}]', '{"adjective":"non-recourse"}', NULL, 3, 2533, NULL),
(2534, 'recover', '/rɪˈkʌvər/', 'verb', '{"zh-TW":["恢復；找回","恢復；復原","收回"],"en":["to return to a normal state","to get back something lost","to return to normal"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"cover","meaning":"cover/get (取得)"},"logic":"取回原來的狀態，即「恢復」。"}', 'recover from / fully recover / recover data; recover from / recover losses / full recovery', '[{"en":"She is recovering from surgery.","zh-TW":"她正在從手術中恢復。"},{"en":"The economy is slowly recovering.","zh-TW":"經濟正在緩慢復甦。"},{"en":"We managed to recover the lost data.","zh-TW":"我們設法恢復了丟失的數據。"}]', '{"noun":"recovery","adjective":"recoverable"}', NULL, 3, 2534, 712),
(2535, 'recreation', '/ˌrɛkriˈeɪʃən/', 'noun', '{"zh-TW":["休閒；娛樂"],"en":["activities done for enjoyment"]}', NULL, 'recreation center / outdoor recreation', '[{"en":"The park is used for recreation.","zh-TW":"這個公園用於休閒活動。"},{"en":"Swimming is a popular form of recreation.","zh-TW":"游泳是一種受歡迎的休閒活動。"}]', '{"adjective":"recreational"}', NULL, 4, 2535, NULL),
(2536, 'recruit', '/rɪˈkruːt/', 'verb', '{"zh-TW":["招募；招聘"],"en":["to find new people to join"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cruit","meaning":"grow (生長)"}}', 'recruit new employees / recruit talent / recruitment drive', '[{"en":"We are recruiting for several positions.","zh-TW":"我們正在招聘幾個職位。"},{"en":"The company recruited 50 new graduates.","zh-TW":"公司招募了50名應屆畢業生。"}]', '{"noun":"recruitment, recruiter, recruit"}', NULL, 3, 2536, NULL),
(2537, 'recruitment', '/rɪˈkruːtmənt/', 'noun', '{"zh-TW":["招募；招聘"],"en":["the process of finding and hiring candidates for jobs"]}', NULL, 'recruitment process / recruitment agency / talent recruitment', '[{"en":"The recruitment campaign attracted hundreds of applicants.","zh-TW":"招募活動吸引了數百名申請者。"},{"en":"Online recruitment platforms have transformed hiring.","zh-TW":"線上招募平台改變了招聘方式。"}]', '{"verb":"recruit","noun":"recruiter"}', NULL, 4, 2537, 433),
(2538, 'recycling', '/rɪˈsaɪklɪŋ/', 'noun', '{"zh-TW":["回收再利用"],"en":["converting waste into reusable material"]}', NULL, 'recycling program / recycling rate', '[{"en":"The city launched a new recycling program last year.","zh-TW":"市政府去年推出了新的回收計劃。"},{"en":"Recycling aluminum cans saves significant energy.","zh-TW":"回收鋁罐可節省大量能源。"}]', '{"verb":"recycle","adjective":"recyclable"}', NULL, 3, 2538, NULL),
(2539, 'reduce', '/rɪˈdjuːs/', 'verb', '{"zh-TW":["減少；降低"],"en":["to make smaller in size or amount"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"duce","meaning":"lead (引導)"}}', 'reduce costs / reduce emissions / reduce the risk', '[{"en":"We need to reduce operating costs.","zh-TW":"我們需要降低營運成本。"},{"en":"The new policy aims to reduce emissions.","zh-TW":"新政策旨在減少排放。"}]', '{"noun":"reduction"}', NULL, 2, 2539, 194),
(2540, 'reduction', 'rɪˈdʌkʃən', 'noun', '{"zh-TW":["減少；降低","縮減"],"en":["a decrease in amount","the act of making smaller"]}', NULL, 'cost reduction/price reduction', '[{"en":"Cost reduction is a key business objective.","zh-TW":"降低成本是主要的業務目標。"}]', '{"verb":"reduce","adjective":"reduced","adverb":"reducibly"}', NULL, 3, 2540, NULL),
(2541, 'redundancy', '/rɪˈdʌndənsi/', 'noun', '{"zh-TW":["裁員；多餘"],"en":["the elimination of a job because it is no longer needed"]}', NULL, 'compulsory redundancy / voluntary redundancy / face redundancy', '[{"en":"Automation led to widespread redundancy in the factory.","zh-TW":"自動化導致工廠出現大規模裁員。"},{"en":"She took voluntary redundancy and started her own business.","zh-TW":"她選擇自願離職並創辦了自己的事業。"}]', '{"adjective":"redundant"}', NULL, 4, 2541, NULL),
(2542, 'redundant', '/rɪˈdʌndənt/', 'adjective', '{"zh-TW":["多餘的；被裁員的"],"en":["no longer needed; also describes a worker whose job has been eliminated"]}', NULL, 'made redundant / redundant position / redundant system', '[{"en":"He was made redundant when his department was downsized.","zh-TW":"他的部門縮編後，他遭到了裁員。"},{"en":"The redundant data backup system provided extra security.","zh-TW":"多餘的資料備份系統提供了額外的安全保障。"}]', '{"verb":"make redundant","noun":"redundancy"}', NULL, 3, 2542, NULL),
(2543, 'refer', '/rɪˈfɜːr/', 'verb', '{"zh-TW":["提到；參考","轉介"],"en":["to mention","to direct someone"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'refer to / refer sb. to / with reference to', '[{"en":"Please refer to the user manual.","zh-TW":"請參考用戶手冊。"},{"en":"I was referred to the HR department.","zh-TW":"我被轉介到人資部門。"}]', '{"noun":"reference, referral, referee"}', NULL, 2, 2543, 51),
(2544, 'referee', '/ˌrɛfəˈriː/', 'noun', '{"zh-TW":["裁判"],"en":["a person who makes sure rules are followed in a game"]}', NULL, 'referee a match / referee''s decision', '[{"en":"The referee blew the whistle.","zh-TW":"裁判吹響了哨子。"},{"en":"The referee''s decision is final.","zh-TW":"裁判的決定是最終的。"}]', NULL, NULL, 3, 2544, NULL),
(2545, 'reference', '/ˈrɛfərəns/', 'noun', '{"zh-TW":["參考；參照","推薦信"],"en":["a source of information","a letter of recommendation"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry"},"suffix":{"text":"-ence","meaning":"名詞後綴"}}', 'for reference / reference number / provide references', '[{"en":"Please keep this for future reference.","zh-TW":"請保留此文件以供未來參考。"},{"en":"Can you provide two professional references?","zh-TW":"你能提供兩份專業推薦嗎？"}]', '{"verb":"refer"}', NULL, 3, 2545, NULL),
(2546, 'referral', '/rɪˈfɜːrəl/', 'noun', '{"zh-TW":["轉介；轉診"],"en":["a direction of a patient to a specialist"]}', NULL, 'get a referral / specialist referral', '[{"en":"You need a referral from your primary doctor to see a specialist.","zh-TW":"您需要主治醫師的轉介才能看專科醫生。"},{"en":"The referral was approved by the insurance company.","zh-TW":"轉介已獲保險公司批准。"}]', '{"verb":"refer"}', NULL, 3, 2546, NULL),
(2547, 'refinancing', '/ˌriːˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["再融資"],"en":["replacing an existing loan with a new one, usually at better terms"]}', NULL, 'pursue refinancing / complete refinancing', '[{"en":"The company completed refinancing at a lower interest rate.","zh-TW":"公司以較低的利率完成了再融資。"},{"en":"Refinancing reduced annual debt servicing costs by $2 million.","zh-TW":"再融資將年度償債成本減少了200萬元。"}]', '{"verb":"refinance"}', NULL, 4, 2547, NULL),
(2548, 'refine', '/rɪˈfaɪn/', 'verb', '{"zh-TW":["完善；改善；提煉"],"en":["to make minor improvements to something"]}', NULL, 'refine a process / refine the strategy', '[{"en":"The team refined the proposal based on feedback.","zh-TW":"團隊根據反饋完善了提案。"},{"en":"Refining the manufacturing process reduced defect rates.","zh-TW":"改善製造流程降低了缺陷率。"}]', '{"noun":"refinement","adjective":"refined"}', NULL, 2, 2548, NULL),
(2549, 'reflect', '/rɪˈflɛkt/', 'verb', '{"zh-TW":["反映；反射","反思"],"en":["to show or express","to think carefully"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"flect","meaning":"bend (彎曲)"}}', 'reflect on / reflect changes / reflect the views', '[{"en":"The report reflects the current market conditions.","zh-TW":"報告反映了當前市場狀況。"},{"en":"Take time to reflect on your progress.","zh-TW":"花時間反思你的進展。"}]', '{"noun":"reflection","adjective":"reflective"}', NULL, 3, 2549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2550, 'reforestation', '/ˌriːˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["植樹造林；重新造林"],"en":["planting trees in an area where forest has been removed"]}', NULL, 'reforestation project / reforestation effort', '[{"en":"The charity funds reforestation projects in deforested areas.","zh-TW":"該慈善機構資助毀林地區的植樹造林項目。"},{"en":"Reforestation helps restore biodiversity and absorb carbon.","zh-TW":"植樹造林有助於恢復生物多樣性和吸收碳。"}]', '{"verb":"reforest","adjective":"reforested"}', NULL, 5, 2550, NULL),
(2551, 'reform', '/rɪˈfɔːrm/', 'noun', '{"zh-TW":["改革"],"en":["a change made to improve a system","a change made to improve something"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"form","meaning":"form/shape (形成)"},"logic":"重新形成，即「改革」。"}', 'education reform / tax reform / reform the system; economic reform / reform the system / tax reform', '[{"en":"The government introduced economic reforms.","zh-TW":"政府推行了經濟改革。"},{"en":"Healthcare reform is urgently needed.","zh-TW":"醫療改革迫在眉睫。"},{"en":"The government announced major tax reforms.","zh-TW":"政府宣布了重大稅制改革。"},{"en":"Healthcare reform is a priority.","zh-TW":"醫療改革是優先事項。"}]', '{"verb":"reform","noun2":"reformer","noun":"reformer"}', NULL, 2, 2551, NULL),
(2552, 'reformulate', '/riːˈfɔːrmjʊleɪt/', 'verb', '{"zh-TW":["重新制定；重新配製"],"en":["to revise or change the formulation of a plan, policy, or product"]}', NULL, 'reformulate the strategy / reformulate the product', '[{"en":"The company reformulated the product to remove allergens.","zh-TW":"公司重新配製了產品以去除過敏原。"},{"en":"Management reformulated its growth strategy after market conditions changed.","zh-TW":"市場條件變化後，管理層重新制定了增長策略。"}]', '{"noun":"reformulation","adjective":"reformulated"}', NULL, 4, 2552, NULL),
(2553, 'refund', '/ˈriːfʌnd/', 'noun', '{"zh-TW":["退款"],"en":["money returned to a buyer"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"fund","meaning":"pour/money (注入/資金)"},"logic":"把錢倒回去，即「退款」。"}', 'full refund / request a refund; full refund / request a refund / refund policy', '[{"en":"I would like to request a refund.","zh-TW":"我想要求退款。"},{"en":"They issued a full refund within 24 hours.","zh-TW":"他們在24小時內全額退款。"},{"en":"We will issue a full refund.","zh-TW":"我們將全額退款。"},{"en":"Please check our refund policy.","zh-TW":"請查看我們的退款政策。"}]', '{"verb":"refund","adjective":"refundable"}', NULL, 2, 2553, 195),
(2554, 'regard', '/rɪˈɡɑːrd/', 'verb', '{"zh-TW":["認為；看待"],"en":["to consider; to think of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch (看)"}}', 'regard as / with regard to / in this regard / regardless', '[{"en":"She is widely regarded as an expert.","zh-TW":"她被廣泛認為是專家。"},{"en":"With regard to your inquiry, please see below.","zh-TW":"關於您的詢問，請見下方。"}]', '{"noun":"regard, regards","preposition":"regarding"}', NULL, 2, 2554, NULL),
(2555, 'regarding', '/rɪˈɡɑːrdɪŋ/', 'preposition', '{"zh-TW":["關於；有關"],"en":["with reference to; concerning"]}', NULL, 'regarding the matter / regarding your inquiry', '[{"en":"I am writing regarding the invoice dated March 10th.","zh-TW":"我寫信是關於3月10日的發票。"},{"en":"Regarding your inquiry, please see the attached response.","zh-TW":"關於您的查詢，請參閱附件的回覆。"}]', '{"verb":"regard","noun":"regard"}', NULL, 3, 2555, NULL),
(2556, 'regardless', '/rɪˈɡɑːrdləs/', 'adverb', '{"zh-TW":["不管；無論如何"],"en":["without being affected by"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch"},"suffix":{"text":"-less","meaning":"without (無)"}}', 'regardless of / regardless of the cost', '[{"en":"We will proceed regardless of the obstacles.","zh-TW":"無論有什麼障礙我們都將繼續。"},{"en":"The rule applies regardless of seniority.","zh-TW":"規則不論資歷均適用。"}]', NULL, NULL, 4, 2556, NULL),
(2557, 'region', '/ˈriːdʒən/', 'noun', '{"zh-TW":["地區；區域"],"en":["a particular area or part"]}', NULL, 'in the region / regional office / Asia-Pacific region', '[{"en":"The company has offices in every region.","zh-TW":"公司在每個地區都有辦公室。"},{"en":"Economic growth varies by region.","zh-TW":"經濟增長因地區而異。"}]', '{"adjective":"regional","adverb":"regionally"}', NULL, 2, 2557, NULL),
(2558, 'register', '/ˈredʒɪstər/', 'noun', '{"zh-TW":["收銀機；登記","登記；註冊"],"en":["a cash register","to officially record information","to officially record or enroll"]}', '{"root":{"text":"gest","meaning":"carry (攜帶)"},"prefix":{"text":"re-","meaning":"back (回)"},"logic":"帶回紀錄，指登記或收銀機。"}', 'cash register / register for a course; register for / register a complaint / registered office', '[{"en":"The cashier opened the register to make change.","zh-TW":"收銀員打開收銀機找零。"},{"en":"Please register at the front desk.","zh-TW":"請在前台登記。"},{"en":"You must register before attending the event.","zh-TW":"參加活動前必須註冊。"},{"en":"The company is registered in Delaware.","zh-TW":"公司在德拉瓦州註冊。"}]', '{"noun":"registration","adjective":"registered"}', NULL, 3, 2558, 52),
(2559, 'registration', 'ˌrɛdʒɪˈstreɪʃən', 'noun', '{"zh-TW":["登記；註冊","掛號"],"en":["the process of signing up","an official record"]}', NULL, 'online registration/event registration', '[{"en":"Registration closes on Friday.","zh-TW":"登記在週五截止。"}]', '{"verb":"register","adjective":"registered"}', NULL, 4, 2559, 613),
(2560, 'regulate', '/ˈrɛɡjuleɪt/', 'verb', '{"zh-TW":["規範；調節","監管；調節"],"en":["to control something by rules","to control or supervise by rules","to control by rules"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其按規則運行，即「規範」。"}', 'regulate industry / government regulated; regulate the industry / regulate temperature; regulate the industry / strictly regulated', '[{"en":"The government regulates the banking industry.","zh-TW":"政府規範銀行業。"},{"en":"This law regulates food safety.","zh-TW":"這項法律規範食品安全。"},{"en":"This thermostat regulates room temperature.","zh-TW":"這個恆溫器調節室溫。"},{"en":"The government regulates the financial sector.","zh-TW":"政府監管金融業。"},{"en":"Prices are regulated by market forces.","zh-TW":"價格由市場力量調節。"}]', '{"noun":"regulation","noun2":"regulator","adjective":"regulatory"}', NULL, 3, 2560, NULL),
(2561, 'regulation', '/ˌrɛɡjuˈleɪʃən/', 'noun', '{"zh-TW":["法規；規定"],"en":["an official rule or law"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'comply with regulations / safety regulations / government regulation', '[{"en":"All companies must comply with safety regulations.","zh-TW":"所有公司必須遵守安全法規。"},{"en":"New regulations take effect next month.","zh-TW":"新法規下月生效。"}]', '{"verb":"regulate","adjective":"regulatory","noun":"regulator"}', NULL, 4, 2561, 434),
(2562, 'rehabilitation', '/ˌriːhəˌbɪlɪˈteɪʃən/', 'noun', '{"zh-TW":["復健；康復治療"],"en":["therapy to restore health or ability after injury"]}', NULL, 'physical rehabilitation / rehabilitation program', '[{"en":"She attended rehabilitation sessions twice a week.","zh-TW":"她每週兩次參加復健課程。"},{"en":"The rehabilitation program helped him regain full mobility.","zh-TW":"復健計劃幫助他恢復了完全的行動能力。"}]', '{"verb":"rehabilitate","adjective":"rehabilitated"}', NULL, 5, 2562, NULL),
(2563, 'rehearsal', '/rɪˈhɜːrsəl/', 'noun', '{"zh-TW":["排練；彩排"],"en":["a practice session before a performance"]}', NULL, 'dress rehearsal / rehearsal room', '[{"en":"We have rehearsal every evening this week.","zh-TW":"這週我們每晚都有排練。"},{"en":"The dress rehearsal is tomorrow.","zh-TW":"彩排在明天。"}]', '{"verb":"rehearse"}', NULL, 3, 2563, NULL),
(2564, 'reimbursable', '/ˌriːɪmˈbɜːrsəbəl/', 'adjective', '{"zh-TW":["可報銷的"],"en":["able to be repaid or compensated"]}', NULL, 'reimbursable expense / reimbursable cost', '[{"en":"Travel costs are reimbursable upon submission of receipts.","zh-TW":"提交收據後差旅費用可以報銷。"},{"en":"Check which expenses are reimbursable under the policy.","zh-TW":"請查看政策下哪些費用可以報銷。"}]', NULL, NULL, 4, 2564, 920),
(2565, 'reimburse', '/ˌriːɪmˈbɜːrs/', 'verb', '{"zh-TW":["報銷；償還"],"en":["to pay back money spent"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"im-burse","meaning":"purse (錢包)"}}', 'reimburse expenses / reimburse sb. for / reimbursement policy', '[{"en":"The company will reimburse travel expenses.","zh-TW":"公司將報銷差旅費。"},{"en":"You will be reimbursed within 30 days.","zh-TW":"你將在30天內獲得報銷。"}]', '{"noun":"reimbursement"}', NULL, 3, 2565, 53),
(2566, 'reimbursement', '/ˌriːɪmˈbɜːrsmənt/', 'noun', '{"zh-TW":["報銷；補償"],"en":["repayment for expenses incurred"]}', NULL, 'expense reimbursement / request reimbursement', '[{"en":"Submit your receipts to receive reimbursement.","zh-TW":"提交收據以獲得報銷。"},{"en":"Business travel expenses will be reimbursed within two weeks.","zh-TW":"商務旅行費用將在兩週內報銷。"}]', '{"verb":"reimburse","adjective":"reimbursed"}', NULL, 5, 2566, 614),
(2567, 'reinforce', '/ˌriːɪnˈfɔːrs/', 'verb', '{"zh-TW":["加強；鞏固"],"en":["to make stronger"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"in-force","meaning":"strengthen (加強)"}}', 'reinforce the message / reinforce a policy', '[{"en":"This reinforces our commitment to quality.","zh-TW":"這強化了我們對品質的承諾。"},{"en":"Training reinforces best practices.","zh-TW":"培訓鞏固了最佳做法。"}]', '{"noun":"reinforcement"}', NULL, 3, 2567, 714),
(2568, 'reinstate', '/ˌriːɪnˈsteɪt/', 'verb', '{"zh-TW":["恢復；重新啟用"],"en":["to restore something to its previous position or status"]}', NULL, 'reinstate a policy / reinstate an employee', '[{"en":"The suspended policy was reinstated after regulatory review.","zh-TW":"暫停的政策在監管審查後恢復了。"},{"en":"The dismissed employee was reinstated following a successful appeal.","zh-TW":"被解雇的員工在成功上訴後被恢復職位。"}]', '{"noun":"reinstatement","adjective":"reinstated"}', NULL, 3, 2568, NULL),
(2569, 'reinvest', '/ˌriːɪnˈvɛst/', 'verb', '{"zh-TW":["再投資"],"en":["to invest money gained back into the same or different ventures"]}', NULL, 'reinvest profits / reinvest in the business', '[{"en":"The company decided to reinvest its profits into research.","zh-TW":"公司決定將利潤再投資於研究。"},{"en":"Reinvesting dividends can significantly grow your wealth over time.","zh-TW":"再投資股息可以隨時間大幅增加您的財富。"}]', '{"noun":"reinvestment","adjective":"reinvested"}', NULL, 3, 2569, NULL),
(2570, 'reject', '/rɪˈdʒekt/', 'verb', '{"zh-TW":["拒絕；駁回"],"en":["to refuse to accept or consider","to refuse to accept"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ject","meaning":"throw (丟)"},"logic":"丟回去，即「拒絕」。"}', 'reject an offer / reject a proposal; reject a proposal / reject an application / flat out reject', '[{"en":"The committee rejected his proposal.","zh-TW":"委員會駁回了他的提案。"},{"en":"She rejected the job offer.","zh-TW":"她拒絕了這份工作邀約。"},{"en":"The board rejected the merger proposal.","zh-TW":"董事會駁回了合併提案。"},{"en":"Her application was rejected.","zh-TW":"她的申請被拒絕了。"}]', '{"noun":"rejection"}', NULL, 2, 2570, NULL),
(2571, 'rejection', '/rɪˈdʒɛkʃən/', 'noun', '{"zh-TW":["拒絕；駁回"],"en":["the dismissal of something or someone"]}', NULL, 'face rejection / rejection letter', '[{"en":"She received a rejection letter from the university.","zh-TW":"她收到了大學的拒絕信。"},{"en":"Rejection of the proposal was unexpected but prompted a revision.","zh-TW":"提案被拒絕出乎意料，但促使了修訂。"}]', '{"verb":"reject","adjective":"rejected"}', NULL, 3, 2571, 435),
(2572, 'relate', '/rɪˈleɪt/', 'verb', '{"zh-TW":["與...有關","敘述"],"en":["to connect or be relevant","to tell"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"late","meaning":"carry (攜帶)"}}', 'relate to / related to / in relation to', '[{"en":"This issue relates to our earlier discussion.","zh-TW":"這問題與我們之前的討論有關。"},{"en":"The increase is related to market demand.","zh-TW":"增長與市場需求有關。"}]', '{"noun":"relation, relationship","adjective":"related, relative","adverb":"relatively"}', NULL, 2, 2572, NULL),
(2573, 'relationship', 'rɪˈleɪʃənʃɪp', 'noun', '{"zh-TW":["關係；關聯","業務關係"],"en":["a connection between people","how things are connected"]}', NULL, 'business relationship/working relationship', '[{"en":"Strong client relationships lead to success.","zh-TW":"強大的客戶關係帶來成功。"}]', '{"adjective":"relational","adverb":"relationally"}', NULL, 4, 2573, 436),
(2574, 'release', '/rɪˈliːs/', 'verb', '{"zh-TW":["發布；釋放"],"en":["to make available; to set free"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"lease","meaning":"let go (放開)"}}', 'release a product / press release / release information', '[{"en":"The company will release the new product in March.","zh-TW":"公司將於三月發布新產品。"},{"en":"A press release was issued today.","zh-TW":"今天發布了新聞稿。"}]', '{"noun":"release"}', NULL, 3, 2574, 197),
(2575, 'relevant', '/ˈreləvənt/', 'adjective', '{"zh-TW":["相關的；切題的"],"en":["closely connected to the matter at hand","closely connected to the matter"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"lev","meaning":"raise (提起)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能再次被提起的重要資訊，即「相關的」。"}', 'relevant experience / relevant information / highly relevant; relevant experience / relevant to / relevant information', '[{"en":"Please include all relevant information.","zh-TW":"請包含所有相關資訊。"},{"en":"Her experience is highly relevant to this position.","zh-TW":"她的經驗與這個職位高度相關。"},{"en":"Please include all relevant experience on your resume.","zh-TW":"請在履歷中包含所有相關經驗。"},{"en":"This is not relevant to the discussion.","zh-TW":"這與討論無關。"}]', '{"noun":"relevance","adverb":"relevantly"}', NULL, 3, 2575, NULL),
(2576, 'reliable', '/rɪˈlaɪəbl/', 'adjective', '{"zh-TW":["可靠的；可信賴的"],"en":["able to be trusted"]}', '{"root":{"text":"rely","meaning":"depend (依賴)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reliable source / reliable service / highly reliable', '[{"en":"We need a reliable supplier.","zh-TW":"我們需要可靠的供應商。"},{"en":"The system has proven to be highly reliable.","zh-TW":"系統已被證明非常可靠。"}]', '{"noun":"reliability","adverb":"reliably","verb":"rely"}', NULL, 3, 2576, 437),
(2577, 'relief', '/rɪˈliːf/', 'noun', '{"zh-TW":["緩解；減輕","救濟"],"en":["the feeling of comfort after anxiety","aid given"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"lief","meaning":"lift (舉起)"}}', 'tax relief / disaster relief / to one''s relief / provide relief', '[{"en":"The tax relief benefits small businesses.","zh-TW":"稅收減免有利於小企業。"},{"en":"To our relief, the problem was resolved quickly.","zh-TW":"令我們欣慰的是，問題很快解決了。"}]', '{"verb":"relieve"}', NULL, 2, 2577, NULL),
(2578, 'reluctant', '/rɪˈlʌktənt/', 'adjective', '{"zh-TW":["不情願的","不情願的；勉強的"],"en":["unwilling and hesitant","unwilling to do something"]}', '{"prefix":{"text":"re-","meaning":"against (反對)"},"root":{"text":"luct","meaning":"struggle (掙扎)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對某事掙扎抗拒的，即「不情願的」。"}', 'reluctant to / a reluctant participant; reluctant to do / be reluctant', '[{"en":"He was reluctant to admit his mistake.","zh-TW":"他不情願承認自己的錯誤。"},{"en":"She was a reluctant participant in the debate.","zh-TW":"她是辯論中不情願的參與者。"},{"en":"He was reluctant to accept the transfer.","zh-TW":"他不情願接受調動。"},{"en":"Many employees are reluctant to change.","zh-TW":"許多員工不願意改變。"}]', '{"noun":"reluctance","adverb":"reluctantly"}', NULL, 3, 2578, NULL),
(2579, 'rely', '/rɪˈlaɪ/', 'verb', '{"zh-TW":["依賴；信賴","依賴；依靠"],"en":["to depend on with full trust","to depend on with confidence"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ly","meaning":"bind (綁)"},"logic":"被綁回到某人身上（依靠），即「依賴」。"}', 'rely on / rely heavily on; rely on / rely heavily on / reliable', '[{"en":"We rely on technology for communication.","zh-TW":"我們依賴科技來溝通。"},{"en":"You can rely on her to do a good job.","zh-TW":"你可以信賴她會做好。"},{"en":"We rely heavily on technology.","zh-TW":"我們嚴重依賴技術。"},{"en":"You can rely on our team to deliver.","zh-TW":"你可以依靠我們團隊交付。"}]', '{"adjective":"reliable","noun":"reliance","noun2":"reliability"}', NULL, 1, 2579, NULL),
(2580, 'remain', '/rɪˈmeɪn/', 'verb', '{"zh-TW":["保持；仍然是","剩餘"],"en":["to continue in the same state","to be left"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"main","meaning":"stay (停留)"}}', 'remain unchanged / remain competitive / remaining balance', '[{"en":"Prices remain stable this quarter.","zh-TW":"本季度價格保持穩定。"},{"en":"Several issues remain unresolved.","zh-TW":"幾個問題仍未解決。"}]', '{"noun":"remainder, remains","adjective":"remaining"}', NULL, 2, 2580, 198),
(2581, 'remarkable', '/rɪˈmɑːrkəbl/', 'adjective', '{"zh-TW":["卓越的；非凡的"],"en":["worthy of attention; extraordinary"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mark","meaning":"notice (注意)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'remarkable achievement / remarkable growth', '[{"en":"The company has shown remarkable growth.","zh-TW":"公司展現了非凡的增長。"},{"en":"Her performance was truly remarkable.","zh-TW":"她的表現真正非凡。"}]', '{"adverb":"remarkably"}', NULL, 4, 2581, NULL),
(2582, 'remediation', '/rɪˌmiːdiˈeɪʃən/', 'noun', '{"zh-TW":["補救措施；修復"],"en":["the action of rectifying a problem, error, or environmental issue"]}', NULL, 'complete remediation / remediation plan', '[{"en":"The company implemented a remediation plan after the audit findings.","zh-TW":"公司在審計發現後實施了補救措施計劃。"},{"en":"Environmental remediation was required before the land could be redeveloped.","zh-TW":"在土地重新開發前需要進行環境修復。"}]', '{"verb":"remediate"}', NULL, 4, 2582, NULL),
(2583, 'remedy', '/ˈrɛmɪdi/', 'noun', '{"zh-TW":["補救措施；療法"],"en":["a solution to a problem"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"med","meaning":"heal (治療)"}}', 'find a remedy / legal remedy / remedy the situation', '[{"en":"We must find a remedy for this issue.","zh-TW":"我們必須找到解決方案。"},{"en":"Legal remedies are available.","zh-TW":"可採取法律補救措施。"}]', '{"verb":"remedy","adjective":"remedial"}', NULL, 2, 2583, NULL),
(2584, 'remember', '/rɪˈmɛmbər/', 'verb', '{"zh-TW":["記得；想起"],"en":["to have in mind","to recall"]}', NULL, 'remember to / if I remember correctly', '[{"en":"Remember to submit the report.","zh-TW":"記得提交報告。"},{"en":"If I remember correctly, the deadline is Friday.","zh-TW":"如果我沒記錯，截止日期是週五。"}]', '{"verb":"remember","noun":"remembrance"}', NULL, 3, 2584, NULL),
(2585, 'remind', '/rɪˈmaɪnd/', 'verb', '{"zh-TW":["提醒"],"en":["to cause someone to remember"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mind","meaning":"mind (心智)"}}', 'remind sb. of / remind sb. to do / a reminder', '[{"en":"Please remind me to call the client.","zh-TW":"請提醒我打給客戶。"},{"en":"This is a reminder that reports are due Friday.","zh-TW":"這是提醒：報告週五到期。"}]', '{"noun":"reminder"}', NULL, 2, 2585, 199),
(2586, 'reminder', 'rɪˈmaɪndər', 'noun', '{"zh-TW":["提醒；提示","催促"],"en":["a message to make someone remember","a note to remind"]}', NULL, 'send a reminder/friendly reminder', '[{"en":"Please send a reminder to all attendees.","zh-TW":"請向所有出席者發送提醒。"}]', '{"verb":"remind","adjective":"reminded"}', NULL, 3, 2586, NULL),
(2587, 'remittance', '/rɪˈmɪtəns/', 'noun', '{"zh-TW":["匯款；匯寄"],"en":["a sum of money sent to someone abroad"]}', NULL, 'send a remittance / remittance service', '[{"en":"She sent a monthly remittance to support her family abroad.","zh-TW":"她每月匯款支持她在國外的家人。"},{"en":"Remittance fees vary between service providers.","zh-TW":"匯款費用因服務提供商而異。"}]', '{"verb":"remit"}', NULL, 4, 2587, NULL),
(2588, 'remote', '/rɪˈmoʊt/', 'adjective', '{"zh-TW":["遠程的；偏遠的"],"en":["far away; operating from a distance"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"mote","meaning":"move (移動)"}}', 'remote work / remote access / remote location', '[{"en":"Most employees now work remotely.","zh-TW":"大多數員工現在遠程工作。"},{"en":"Remote access to the system is available.","zh-TW":"系統可以遠程訪問。"}]', '{"adverb":"remotely","noun":"remoteness"}', NULL, 2, 2588, NULL),
(2589, 'remove', '/rɪˈmuːv/', 'verb', '{"zh-TW":["移除；消除"],"en":["to take away"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"move","meaning":"move (移動)"}}', 'remove from / remove obstacles / remove barriers', '[{"en":"Please remove your belongings from the desk.","zh-TW":"請把你的物品從桌上移走。"},{"en":"We need to remove barriers to entry.","zh-TW":"我們需要消除進入障礙。"}]', '{"noun":"removal","adjective":"removable"}', NULL, 2, 2589, NULL),
(2590, 'remuneration', '/rɪˌmjuːnəˈreɪʃən/', 'noun', '{"zh-TW":["報酬；薪資"],"en":["payment or reward for work or services provided"]}', NULL, 'total remuneration / remuneration package / executive remuneration', '[{"en":"The remuneration committee sets executive pay levels.","zh-TW":"薪酬委員會確定高管薪資水準。"},{"en":"Remuneration should reflect the employee''s level of responsibility.","zh-TW":"報酬應反映員工的責任水準。"}]', '{"verb":"remunerate","adjective":"remunerative"}', NULL, 4, 2590, 922),
(2591, 'renegotiate', '/ˌriːnɪˈɡoʊʃieɪt/', 'verb', '{"zh-TW":["重新談判；重新協商"],"en":["to negotiate the terms of an existing agreement again"]}', NULL, 'renegotiate a contract / renegotiate payment terms', '[{"en":"The company renegotiated its supplier contracts to reduce costs.","zh-TW":"公司重新談判了供應商合約以降低成本。"},{"en":"Loan terms were renegotiated to improve cash flow.","zh-TW":"貸款條款重新談判以改善現金流。"}]', '{"noun":"renegotiation","adjective":"renegotiated"}', NULL, 4, 2591, NULL),
(2592, 'renew', '/rɪˈnjuː/', 'verb', '{"zh-TW":["更新；續約"],"en":["to make valid for another period"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"new","meaning":"new (新)"}}', 'renew a contract / renew a subscription / renewal date', '[{"en":"Don''t forget to renew your license.","zh-TW":"別忘了更新你的執照。"},{"en":"The contract was renewed for another year.","zh-TW":"合約續約了一年。"}]', '{"noun":"renewal","adjective":"renewable"}', NULL, 2, 2592, 716),
(2593, 'renewal', 'rɪˈnjuːəl', 'noun', '{"zh-TW":["續約；更新","復甦"],"en":["the act of renewing","continuing after a period"]}', NULL, 'contract renewal/subscription renewal', '[{"en":"Please confirm your contract renewal.","zh-TW":"請確認您的合約續簽。"}]', '{"verb":"renew","adjective":"renewable"}', NULL, 3, 2593, 439),
(2594, 'renovate', '/ˈrɛnəveɪt/', 'verb', '{"zh-TW":["翻新；修繕","翻修"],"en":["to repair and improve a building","to restore to good condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'renovate the office / recently renovated; renovate the building / newly renovated', '[{"en":"The office was recently renovated.","zh-TW":"辦公室最近進行了翻新。"},{"en":"They plan to renovate the building.","zh-TW":"他們計劃翻新大樓。"},{"en":"The hotel was recently renovated.","zh-TW":"酒店最近翻新了。"},{"en":"Plans to renovate the office were approved.","zh-TW":"翻新辦公室的計劃已獲批。"}]', '{"noun":"renovation"}', NULL, 3, 2594, NULL),
(2595, 'renovation', '/ˌrenəˈveɪʃən/', 'noun', '{"zh-TW":["翻新；整修"],"en":["the process of improving or restoring a building to good condition"]}', NULL, 'property renovation / renovation project / renovation costs', '[{"en":"The office underwent major renovation over the summer.","zh-TW":"辦公室在夏季進行了大規模翻新。"},{"en":"Renovation costs were higher than initially budgeted.","zh-TW":"翻新費用高於最初預算。"}]', '{"verb":"renovate","adjective":"renovated"}', NULL, 4, 2595, NULL),
(2596, 'rent', '/rɛnt/', 'noun', '{"zh-TW":["租金"],"en":["payment for use of property"]}', NULL, 'pay rent / rent out / for rent / rental agreement', '[{"en":"Office rent has increased significantly.","zh-TW":"辦公室租金大幅上漲。"},{"en":"The apartment is available for rent.","zh-TW":"公寓可供出租。"}]', '{"verb":"rent","noun":"rental, renter"}', NULL, 1, 2596, NULL),
(2597, 'reorganize', 'riːˈɔːrɡənaɪz', 'verb', '{"zh-TW":["重組；重新整理","調整"],"en":["to arrange differently","to restructure"]}', NULL, 'reorganize a department/reorganize files', '[{"en":"Management decided to reorganize the team.","zh-TW":"管理層決定重組團隊。"}]', '{"noun":"reorganization","adjective":"reorganized"}', NULL, 4, 2597, NULL),
(2598, 'repair', '/rɪˈpɛr/', 'verb', '{"zh-TW":["修理；修復"],"en":["to fix something broken"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"pair","meaning":"prepare (準備)"}}', 'repair damage / under repair / repair costs', '[{"en":"The equipment is being repaired.","zh-TW":"設備正在維修中。"},{"en":"Repair costs exceeded our estimates.","zh-TW":"修理費用超出了我們的估計。"}]', '{"noun":"repair, reparation"}', NULL, 2, 2598, 54),
(2599, 'repay', '/rɪˈpeɪ/', 'verb', '{"zh-TW":["償還；歸還"],"en":["to pay back money that was borrowed"]}', NULL, 'repay a loan / repay debt / repay in full', '[{"en":"She repaid the business loan ahead of schedule.","zh-TW":"她提前償還了商業貸款。"},{"en":"The investment was repaid with a 15% return within two years.","zh-TW":"投資在兩年內以15%的回報率得到了償還。"}]', '{"noun":"repayment","adjective":"repaid"}', NULL, 2, 2599, NULL);
