(2600, 'replace', '/rɪˈpleɪs/', 'verb', '{"zh-TW":["取代；更換"],"en":["to put something new in place of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"place","meaning":"place (放置)"}}', 'replace with / replace sb. / find a replacement', '[{"en":"We will replace the old system with a new one.","zh-TW":"我們將用新系統取代舊系統。"},{"en":"She was hired to replace the former manager.","zh-TW":"她被聘來接替前任經理。"}]', '{"noun":"replacement","adjective":"replaceable"}', NULL, 3, 2600, 200),
(2601, 'replacement', 'rɪˈpleɪsmənt', 'noun', '{"zh-TW":["更換；替代品","接替者"],"en":["someone or something substituted","the act of replacing"]}', NULL, 'find a replacement/product replacement', '[{"en":"The replacement part arrived yesterday.","zh-TW":"替換零件昨天到達了。"}]', '{"verb":"replace","adjective":"replaceable"}', NULL, 4, 2601, 615),
(2602, 'replenishment', '/rɪˈplenɪʃmənt/', 'noun', '{"zh-TW":["補貨；補充"],"en":["restoring a stock of goods to an adequate level"]}', NULL, 'schedule replenishment / automatic replenishment / stock replenishment', '[{"en":"Automated replenishment reduces the risk of stockouts.","zh-TW":"自動補貨降低了缺貨的風險。"},{"en":"The replenishment order was placed as soon as inventory hit the reorder point.","zh-TW":"庫存一觸及再訂購點就立即下達了補貨訂單。"}]', '{"verb":"replenish","adjective":"replenished"}', NULL, 5, 2602, NULL),
(2603, 'reply', 'rɪˈplaɪ', 'noun', '{"zh-TW":["回覆；答覆","回應"],"en":["an answer to a message","a response"]}', NULL, 'await a reply/in reply to', '[{"en":"We are waiting for your reply.","zh-TW":"我們正在等待您的回覆。"}]', '{"verb":"reply","adjective":"replying"}', NULL, 2, 2603, NULL),
(2604, 'report', '/rɪˈpɔːrt/', 'noun', '{"zh-TW":["報告；報告書"],"en":["a written or spoken account of a topic or event"]}', NULL, 'annual report / submit a report', '[{"en":"The team submitted the quarterly sales report.","zh-TW":"團隊提交了季度銷售報告。"},{"en":"Her report provided valuable insights for management.","zh-TW":"她的報告為管理層提供了寶貴見解。"}]', '{"verb":"report","noun":"reporter","adjective":"reported"}', NULL, 2, 2604, 201),
(2605, 'represent', '/ˌrɛprɪˈzɛnt/', 'verb', '{"zh-TW":["代表；象徵"],"en":["to act or speak for someone; to symbolize"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"present","meaning":"present (呈現)"}}', 'represent the company / represent a change', '[{"en":"She represents the company at trade shows.","zh-TW":"她代表公司參加商展。"},{"en":"This represents a significant change in policy.","zh-TW":"這代表政策的重大改變。"}]', '{"noun":"representation, representative","adjective":"representative"}', NULL, 3, 2605, NULL),
(2606, 'representation', '/ˌreprɪzenˈteɪʃən/', 'noun', '{"zh-TW":["代表；陳述"],"en":["the action of speaking on behalf of someone; also a formal statement"]}', NULL, 'legal representation / seek representation / union representation', '[{"en":"All employees have the right to union representation.","zh-TW":"所有員工都有工會代表的權利。"},{"en":"She provided written representations to the regulatory committee.","zh-TW":"她向監管委員會提交了書面陳述。"}]', '{"verb":"represent","noun":"representative"}', NULL, 5, 2606, 616),
(2607, 'representative', 'ˌrɛprɪˈzɛntətɪv', 'noun', '{"zh-TW":["代表；代理人","業務員"],"en":["a person acting on behalf of another","a sales agent"]}', NULL, 'sales representative/customer representative', '[{"en":"Our sales representative will contact you.","zh-TW":"我們的銷售代表將與您聯繫。"}]', '{"verb":"represent","adjective":"representative","adverb":"representatively"}', NULL, 5, 2607, 440),
(2608, 'repurchase', '/riːˈpɜːrtʃəs/', 'verb', '{"zh-TW":["回購；買回"],"en":["to buy back something previously sold"]}', NULL, 'repurchase shares / repurchase agreement', '[{"en":"The company announced a plan to repurchase 10% of its shares.","zh-TW":"公司宣佈計劃回購10%的股份。"},{"en":"The repurchase agreement was settled within three days.","zh-TW":"回購協議在三天內結算。"}]', '{"noun":"repurchase","adjective":"repurchased"}', NULL, 4, 2608, NULL),
(2609, 'reputation', '/ˌrɛpjuˈteɪʃən/', 'noun', '{"zh-TW":["聲譽；名譽"],"en":["the opinion people have about someone"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"put","meaning":"think (思考)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'good reputation / damage one''s reputation / build a reputation', '[{"en":"The company has an excellent reputation.","zh-TW":"公司享有卓越聲譽。"},{"en":"One mistake can damage your reputation.","zh-TW":"一個錯誤可以損害你的聲譽。"}]', '{"adjective":"reputable"}', NULL, 4, 2609, NULL),
(2610, 'request', '/rɪˈkwɛst/', 'noun', '{"zh-TW":["請求；要求"],"en":["an act of asking for something"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quest","meaning":"seek (尋求)"}}', 'make a request / upon request / request for information', '[{"en":"We received a request for additional funding.","zh-TW":"我們收到了追加資金的請求。"},{"en":"Samples are available upon request.","zh-TW":"樣品可依要求提供。"}]', '{"verb":"request"}', NULL, 3, 2610, 202),
(2611, 'require', '/rɪˈkwaɪər/', 'verb', '{"zh-TW":["需要；要求"],"en":["to need; to demand by rule"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quire","meaning":"seek (尋求)"}}', 'require approval / required by law / as required', '[{"en":"This position requires five years of experience.","zh-TW":"此職位需要五年經驗。"},{"en":"All visitors are required to sign in.","zh-TW":"所有訪客必須登記。"}]', '{"noun":"requirement","adjective":"required"}', NULL, 3, 2611, 55),
(2612, 'required', 'rɪˈkwaɪərd', 'adjective', '{"zh-TW":["必要的；規定的","必須的"],"en":["needed or demanded","obligatory"]}', NULL, 'required documents/required skills', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要文件。"}]', '{"verb":"require","noun":"requirement"}', NULL, 3, 2612, NULL),
(2613, 'requirement', 'rɪˈkwaɪərmənt', 'noun', '{"zh-TW":["要求；需求","條件"],"en":["something that is needed","a necessary condition"]}', NULL, 'meet requirements/list requirements', '[{"en":"Please review the project requirements.","zh-TW":"請查看專案要求。"}]', '{"verb":"require","adjective":"required"}', NULL, 4, 2613, 441),
(2614, 'reschedule', '/ˌriːˈʃedjuːl/', 'verb', '{"zh-TW":["重新安排時間；改期"],"en":["to arrange a new time for a meeting, event, or task"]}', NULL, 'reschedule a meeting / reschedule a delivery', '[{"en":"The client asked to reschedule the meeting to the following week.","zh-TW":"客戶要求將會議改期到下週。"},{"en":"We had to reschedule the product launch due to supply delays.","zh-TW":"由於供應延遲，我們不得不重新安排產品發布時間。"}]', '{"noun":"rescheduling"}', NULL, 4, 2614, NULL),
(2615, 'research', '/rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["研究；調查"],"en":["careful study of a subject"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"search","meaning":"search (搜索)"}}', 'conduct research / research and development / market research', '[{"en":"The company invests heavily in R&D.","zh-TW":"公司大量投資研發。"},{"en":"Further research is needed.","zh-TW":"需要進一步研究。"}]', '{"verb":"research","noun":"researcher"}', NULL, 3, 2615, 203),
(2616, 'reseller', '/riːˈselər/', 'noun', '{"zh-TW":["轉售商；經銷商"],"en":["a business that purchases products to resell them, often adding value"]}', NULL, 'authorized reseller / reseller agreement / reseller program', '[{"en":"The software company works with 300 authorized resellers worldwide.","zh-TW":"軟體公司在全球與300家授權經銷商合作。"},{"en":"Resellers often provide localized support and customization.","zh-TW":"轉售商通常提供本地化支援和客製化服務。"}]', '{"verb":"resell","plural":"resellers"}', NULL, 3, 2616, NULL),
(2617, 'reservation', '/ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["預訂","保留意見"],"en":["a booking","doubt or uncertainty"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'make a reservation / have reservations about / without reservation', '[{"en":"I''d like to make a reservation for two.","zh-TW":"我想預訂兩人座。"},{"en":"I have some reservations about the plan.","zh-TW":"我對計劃有些保留意見。"}]', '{"verb":"reserve"}', NULL, 4, 2617, 56),
(2618, 'reserve', '/rɪˈzɜːrv/', 'verb', '{"zh-TW":["預訂；保留"],"en":["to book; to keep for later use"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serve","meaning":"keep (保持)"}}', 'reserve a room / cash reserves / reserve the right', '[{"en":"Please reserve a conference room.","zh-TW":"請預訂一間會議室。"},{"en":"We reserve the right to cancel.","zh-TW":"我們保留取消的權利。"}]', '{"noun":"reserve, reservation","adjective":"reserved"}', NULL, 3, 2618, 204),
(2619, 'reserves', '/rɪˈzɜːrvz/', 'noun', '{"zh-TW":["儲備金；準備金"],"en":["retained earnings or funds set aside for future needs or contingencies"]}', NULL, 'build up reserves / draw on reserves', '[{"en":"The company built up reserves to fund future expansion.","zh-TW":"公司積累了儲備金以資助未來的擴張。"},{"en":"Reserves provide a buffer against unexpected losses or economic downturns.","zh-TW":"儲備金在意外損失或經濟下滑時提供了緩衝。"}]', NULL, NULL, 3, 2619, NULL),
(2620, 'reside', '/rɪˈzaɪd/', 'verb', '{"zh-TW":["居住"],"en":["to live in a place"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"side","meaning":"sit (坐)"}}', 'reside in / place of residence', '[{"en":"She resides in Tokyo.","zh-TW":"她居住在東京。"},{"en":"Please provide your place of residence.","zh-TW":"請提供您的居住地。"}]', '{"noun":"residence, resident, residency","adjective":"residential"}', NULL, 2, 2620, NULL),
