(2642, 'retail', '/ˈriːteɪl/', 'noun', '{"zh-TW":["零售"],"en":["the sale of goods to the public in small quantities","the sale of goods to the public"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"tail","meaning":"cut (切割)"},"logic":"再次切割分售，即「零售」。"}', 'retail price / retail store / retail industry', '[{"en":"The retail price is higher than the wholesale price.","zh-TW":"零售價比批發價高。"},{"en":"She has years of experience in retail.","zh-TW":"她有多年零售業經驗。"},{"en":"The retail price is $49.99.","zh-TW":"零售價為49.99美元。"},{"en":"She has 10 years of retail experience.","zh-TW":"她有十年零售經驗。"}]', '{"noun":"retailer","verb":"retail"}', NULL, 2, 2642, 445),
