(2649, 'reveal', '/rɪˈviːl/', 'verb', '{"zh-TW":["揭露；顯示","揭示；透露"],"en":["to make known something previously hidden","to make known; to show"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"veal","meaning":"veil/cover (遮蓋)"},"logic":"把遮蓋拉回，即「揭露」。"}', 'reveal the truth / reveal information / reveal a secret; reveal information / reveal the truth / reveal findings', '[{"en":"The investigation revealed new evidence.","zh-TW":"調查揭露了新證據。"},{"en":"She revealed her plans for the future.","zh-TW":"她透露了未來的計畫。"},{"en":"The audit revealed several discrepancies.","zh-TW":"審計揭示了幾處差異。"},{"en":"The survey revealed customer preferences.","zh-TW":"調查揭示了客戶偏好。"}]', '{"noun":"revelation","adjective":"revealing"}', NULL, 2, 2649, NULL);